/** User account item from BFF GET /identity/user-accounts response. */
export type IdentityUserAccount = {
    id: string;
    displayName?: string;
    givenName?: string;
    surname?: string;
    email?: string;
    [key: string]: unknown;
};
/** BFF GET /identity/user-accounts response (array of user accounts). */
export type GetUserDataByAccountIdsResponse = IdentityUserAccount[];
/** Options for useGetUserNames. */
export type UseGetUserNamesOptions = {
    appName?: string;
};
